// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title AtomicSwap
 * @notice Hash Time-Locked Contract (HTLC) for trustless cross-chain atomic swaps
 * @dev Enables direct Token Consciousness Exchange between two parties across chains
 * 
 * How it works:
 * 1. Party A creates swap on Chain 1 with secret hash
 * 2. Party B creates swap on Chain 2 with same secret hash
 * 3. Party A reveals secret and claims Party B's tokens
 * 4. Party B uses revealed secret to claim Party A's tokens
 * 5. If timeout, both parties can refund
 */
contract AtomicSwap is ReentrancyGuard {

    // Swap states
    enum State { EMPTY, OPEN, COMPLETED, REFUNDED, EXPIRED }

    // Swap structure
    struct Swap {
        address initiator;           // Party creating the swap
        address participant;         // Counterparty
        address token;              // Token contract address
        uint256 amount;             // Amount locked
        bytes32 secretHash;         // Hash of secret
        uint256 timelock;           // Expiry timestamp
        State state;                // Current state
    }

    // Swap ID => Swap details
    mapping(bytes32 => Swap) public swaps;

    // Events
    event SwapInitiated(
        bytes32 indexed swapId,
        address indexed initiator,
        address indexed participant,
        address token,
        uint256 amount,
        bytes32 secretHash,
        uint256 timelock
    );

    event SwapCompleted(
        bytes32 indexed swapId,
        address indexed participant,
        bytes32 secret
    );

    event SwapRefunded(
        bytes32 indexed swapId,
        address indexed initiator
    );

    /**
     * @notice Initiate atomic swap
     * @param swapId Unique swap identifier (must match across chains)
     * @param participant Counterparty address
     * @param token Token contract address
     * @param amount Amount to lock
     * @param secretHash Hash of secret (keccak256(secret))
     * @param timelock Expiry timestamp (unix seconds)
     */
    function initiate(
        bytes32 swapId,
        address participant,
        address token,
        uint256 amount,
        bytes32 secretHash,
        uint256 timelock
    ) external nonReentrant {
        require(swaps[swapId].state == State.EMPTY, "Swap already exists");
        require(participant != address(0), "Invalid participant");
        require(participant != msg.sender, "Cannot swap with self");
        require(token != address(0), "Invalid token");
        require(amount > 0, "Amount must be > 0");
        require(secretHash != bytes32(0), "Invalid secret hash");
        require(timelock > block.timestamp, "Timelock must be in future");
        require(timelock <= block.timestamp + 48 hours, "Timelock too far");

        // Transfer tokens to contract
        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );

        // Create swap
        swaps[swapId] = Swap({
            initiator: msg.sender,
            participant: participant,
            token: token,
            amount: amount,
            secretHash: secretHash,
            timelock: timelock,
            state: State.OPEN
        });

        emit SwapInitiated(
            swapId,
            msg.sender,
            participant,
            token,
            amount,
            secretHash,
            timelock
        );
    }

    /**
     * @notice Complete swap by revealing secret
     * @param swapId Swap identifier
     * @param secret Pre-image of secretHash
     */
    function complete(
        bytes32 swapId,
        bytes32 secret
    ) external nonReentrant {
        Swap storage swap = swaps[swapId];

        require(swap.state == State.OPEN, "Swap not open");
        require(msg.sender == swap.participant, "Only participant can complete");
        require(block.timestamp < swap.timelock, "Swap expired");
        require(keccak256(abi.encodePacked(secret)) == swap.secretHash, "Invalid secret");

        // Mark as completed
        swap.state = State.COMPLETED;

        // Transfer tokens to participant
        require(
            IERC20(swap.token).transfer(swap.participant, swap.amount),
            "Transfer failed"
        );

        emit SwapCompleted(swapId, swap.participant, secret);
    }

    /**
     * @notice Refund tokens after timelock expires
     * @param swapId Swap identifier
     */
    function refund(bytes32 swapId) external nonReentrant {
        Swap storage swap = swaps[swapId];

        require(swap.state == State.OPEN, "Swap not open");
        require(msg.sender == swap.initiator, "Only initiator can refund");
        require(block.timestamp >= swap.timelock, "Timelock not expired");

        // Mark as refunded
        swap.state = State.REFUNDED;

        // Return tokens to initiator
        require(
            IERC20(swap.token).transfer(swap.initiator, swap.amount),
            "Transfer failed"
        );

        emit SwapRefunded(swapId, swap.initiator);
    }

    /**
     * @notice Get swap details
     * @param swapId Swap identifier
     */
    function getSwap(bytes32 swapId) external view returns (
        address initiator,
        address participant,
        address token,
        uint256 amount,
        bytes32 secretHash,
        uint256 timelock,
        State state
    ) {
        Swap storage swap = swaps[swapId];
        return (
            swap.initiator,
            swap.participant,
            swap.token,
            swap.amount,
            swap.secretHash,
            swap.timelock,
            swap.state
        );
    }

    /**
     * @notice Check if swap is active
     * @param swapId Swap identifier
     */
    function isActive(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return swap.state == State.OPEN && block.timestamp < swap.timelock;
    }

    /**
     * @notice Check if swap is completable
     * @param swapId Swap identifier
     */
    function isCompletable(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return swap.state == State.OPEN && block.timestamp < swap.timelock;
    }

    /**
     * @notice Check if swap is refundable
     * @param swapId Swap identifier
     */
    function isRefundable(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return swap.state == State.OPEN && block.timestamp >= swap.timelock;
    }

    /**
     * @notice Generate swap ID from parameters
     * @dev Ensures same swap ID across chains
     */
    function generateSwapId(
        address initiator,
        address participant,
        uint256 amount,
        bytes32 secretHash,
        uint256 nonce
    ) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(
            initiator,
            participant,
            amount,
            secretHash,
            nonce
        ));
    }
}

project/contracts/bridges/production/Liq.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title LiquidityPoolBridge
 * @notice Liquidity pool-based bridge for fast token transfers
 * @dev Maintains liquidity pools on both chains, swaps instead of mint/burn
 * 
 * Liquidity providers deposit on both chains and earn fees
 */
contract LiquidityPoolBridge is Ownable, ReentrancyGuard {
    using ECDSA for bytes32;

    IERC20 public immutable btcbr;

    // Pool state
    uint256 public totalLiquidity;
    mapping(address => uint256) public liquidityProviders;

    // Fee configuration (basis points)
    uint256 public transferFee = 30; // 0.3%
    uint256 public lpFeeShare = 25; // 0.25% to LPs
    uint256 public protocolFeeShare = 5; // 0.05% to protocol

    uint256 public accumulatedFees;
    uint256 public lpRewards;

    // Transfer limits
    uint256 public minTransfer = 10 * 10**18;
    uint256 public maxTransfer = 1_000_000 * 10**18;

    // Cross-chain transfer tracking
    mapping(uint256 => bool) public processedNonces;
    mapping(address => bool) public validators;
    uint256 public requiredSignatures = 2;

    event LiquidityAdded(address indexed provider, uint256 amount);
    event LiquidityRemoved(address indexed provider, uint256 amount);
    event TransferInitiated(address indexed from, address indexed to, uint256 amount, uint256 fee, uint256 nonce);
    event TransferCompleted(address indexed to, uint256 amount, uint256 nonce);
    event FeesCollected(uint256 lpFees, uint256 protocolFees);

    constructor(address _btcbr) {
        require(_btcbr != address(0), "Invalid token");
        btcbr = IERC20(_btcbr);
    }

    /**
     * @notice Add liquidity to pool
     */
    function addLiquidity(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");

        require(btcbr.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        liquidityProviders[msg.sender] += amount;
        totalLiquidity += amount;

        emit LiquidityAdded(msg.sender, amount);
    }

    /**
     * @notice Remove liquidity from pool
     */
    function removeLiquidity(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(liquidityProviders[msg.sender] >= amount, "Insufficient liquidity");
        require(totalLiquidity - amount >= minTransfer * 10, "Would drain pool");

        // Calculate LP's share of accumulated rewards
        uint256 share = (lpRewards * amount) / totalLiquidity;

        liquidityProviders[msg.sender] -= amount;
        totalLiquidity -= amount;
        lpRewards -= share;

        require(btcbr.transfer(msg.sender, amount + share), "Transfer failed");

        emit LiquidityRemoved(msg.sender, amount + share);
    }

    /**
     * @notice Initiate cross-chain transfer
     */
    function transfer(address recipient, uint256 amount) external nonReentrant returns (uint256 nonce) {
        require(amount >= minTransfer, "Below minimum");
        require(amount <= maxTransfer, "Above maximum");
        require(recipient != address(0), "Invalid recipient");

        // Calculate fees
        uint256 fee = (amount * transferFee) / 10000;
        uint256 lpFee = (amount * lpFeeShare) / 10000;
        uint256 protocolFee = fee - lpFee;
        uint256 netAmount = amount - fee;

        // Check pool liquidity
        require(totalLiquidity >= netAmount, "Insufficient pool liquidity");

        // Transfer from user
        require(btcbr.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        // Distribute fees
        lpRewards += lpFee;
        accumulatedFees += protocolFee;
        totalLiquidity += netAmount;

        nonce = uint256(keccak256(abi.encodePacked(msg.sender, recipient, amount, block.timestamp)));

        emit TransferInitiated(msg.sender, recipient, netAmount, fee, nonce);
        return nonce;
    }

    /**
     * @notice Complete transfer (called by validators)
     */
    function completeTransfer(
        address recipient,
        uint256 amount,
        uint256 nonce,
        bytes[] calldata signatures
    ) external nonReentrant {
        require(!processedNonces[nonce], "Already processed");
        require(signatures.length >= requiredSignatures, "Insufficient signatures");

        // Verify signatures
        bytes32 message = keccak256(abi.encodePacked(recipient, amount, nonce, block.chainid));
        bytes32 ethSignedMessage = message.toEthSignedMessageHash();

        address[] memory signers = new address[](signatures.length);
        for (uint256 i = 0; i < signatures.length; i++) {
            address signer = ethSignedMessage.recover(signatures[i]);
            require(validators[signer], "Invalid validator");

            for (uint256 j = 0; j < i; j++) {
                require(signers[j] != signer, "Duplicate signature");
            }
            signers[i] = signer;
        }

        processedNonces[nonce] = true;
        totalLiquidity -= amount;

        require(btcbr.transfer(recipient, amount), "Transfer failed");

        emit TransferCompleted(recipient, amount, nonce);
    }

    /**
     * @notice Get LP rewards for address
     */
    function calculateRewards(address provider) external view returns (uint256) {
        if (totalLiquidity == 0) return 0;
        return (lpRewards * liquidityProviders[provider]) / totalLiquidity;
    }

    /**
     * @notice Withdraw protocol fees
     */
    function withdrawFees() external onlyOwner {
        uint256 fees = accumulatedFees;
        accumulatedFees = 0;
        require(btcbr.transfer(owner(), fees), "Transfer failed");
    }

    function addValidator(address validator) external onlyOwner {
        validators[validator] = true;
    }

    function removeValidator(address validator) external onlyOwner {
        validators[validator] = false;
    }

    function setFees(uint256 _transferFee, uint256 _lpFeeShare) external onlyOwner {
        require(_transferFee <= 100, "Fee too high"); // Max 1%
        require(_lpFeeShare <= _transferFee, "LP fee exceeds total");
        transferFee = _transferFee;
        lpFeeShare = _lpFeeShare;
        protocolFeeShare = _transferFee - _lpFeeShare;
    }
}

